/* csilc_enc_CheckValue writes the union as a tagged sum [variant_index, value]. */
static inline int csilc_enc_CheckValue(csilc_buf *b, const CheckValue *v) {
    if (csilc_w_array_head(b, 2)) return -1;
    switch (v->tag) {
    case CHECK_VALUE_TEXT:
        if (csilc_w_uint(b, 0)) return -1;
        if (csilc_w_text(b, (v->u.text), (v->u.text) ? strlen(v->u.text) : 0)) return -1;
        break;
    case CHECK_VALUE_INT:
        if (csilc_w_uint(b, 1)) return -1;
        if (csilc_w_int(b, (int64_t)(v->u.int_))) return -1;
        break;
    case CHECK_VALUE_FLOAT:
        if (csilc_w_uint(b, 2)) return -1;
        if (csilc_w_f64(b, (double)(v->u.float_))) return -1;
        break;
    default: return -1;
    }
    return 0;
}

/* csilc_dec_CheckValue reads a tagged sum [variant_index, value] into the union. */
static inline int csilc_dec_CheckValue(const csilc_value *m, CsilCodecArena *a, CheckValue *out) {
    (void)a;
    uint64_t csilc_idx;
    if (!m || m->kind != CSILC_ARRAY || m->as.array.count != 2) return -1;
    if (!csilc_as_u64(&m->as.array.items[0], &csilc_idx)) return -1;
    switch (csilc_idx) {
    case 0:
        out->tag = CHECK_VALUE_TEXT;
        if (!csilc_get_text(&m->as.array.items[1], &(out->u.text))) return -1;
        return 0;
    case 1:
        out->tag = CHECK_VALUE_INT;
        if (!csilc_as_i64(&m->as.array.items[1], &(out->u.int_))) return -1;
        return 0;
    case 2:
        out->tag = CHECK_VALUE_FLOAT;
        if (!csilc_as_f64(&m->as.array.items[1], &(out->u.float_))) return -1;
        return 0;
    default: return -1;
    }
}

/* csilc_enc_CheckEntries writes CheckEntries as a CBOR map of text keys to encoded values. */
static inline int csilc_enc_CheckEntries(csilc_buf *b, const CheckEntries *v) {
    if (csilc_w_map_head(b, v->count)) return -1;
    for (size_t csilc_i = 0; csilc_i < v->count; csilc_i++) {
        if (csilc_w_text(b, (v->keys[csilc_i]), (v->keys[csilc_i]) ? strlen(v->keys[csilc_i]) : 0)) return -1;
        if (csilc_enc_CheckValue(b, &(v->values[csilc_i]))) return -1;
    }
    return 0;
}

/* csilc_dec_CheckEntries reads CheckEntries from a decoded CBOR map (arena-borrowed). */
static inline int csilc_dec_CheckEntries(const csilc_value *m, CsilCodecArena *a, CheckEntries *out) {
    if (!m || m->kind != CSILC_MAP) return -1;
    out->count = m->as.map.count;
    out->keys = NULL;
    out->values = NULL;
    if (out->count) {
        out->keys = (char * *)csilc_arena_alloc(a, out->count * sizeof(char *));
        out->values = (CheckValue *)csilc_arena_alloc(a, out->count * sizeof(CheckValue));
        if (!out->keys || !out->values) return -1;
        for (size_t csilc_i = 0; csilc_i < out->count; csilc_i++) {
            if (!csilc_get_text(m->as.map.pairs[csilc_i].key, &(out->keys[csilc_i]))) return -1;
            if (csilc_dec_CheckValue(m->as.map.pairs[csilc_i].val, a, &(out->values[csilc_i]))) return -1;
        }
    }
    return 0;
}

